import{describe,it,expect}from"vitest";import{AdaptivePreferenceEngine,chooseCostTier}from"../../frontend/js-modules/adaptive-preference-engine.js";import{EVENT_TYPES}from"../../frontend/js-modules/interaction-tracker.js";const DAY=864e5,NOW=17e11,destinations=[{id:"wild-1",name:"Kaziranga",tags:["wildlife","forests"],budget:"mid",seasons:["winter"]},{id:"beach-1",name:"Goa",tags:["beaches","food"],budget:"mid",seasons:["winter"]},{id:"luxury-1",name:"Udaipur",tags:["heritage"],budget:"luxury",seasons:["winter","summer"]}];function makeEngine(e={}){return new AdaptivePreferenceEngine({destinations:destinations,now:()=>NOW,...e})}describe("chooseCostTier",()=>{it("matches the trip-planner thresholds",()=>{expect(chooseCostTier(1e3,1)).toBe("budget"),expect(chooseCostTier(3e3,1)).toBe("mid"),expect(chooseCostTier(8e3,1)).toBe("luxury")})}),describe("AdaptivePreferenceEngine",()=>{it("reports cold start with no events",()=>{const e=makeEngine().buildProfile([]);expect(AdaptivePreferenceEngine.isColdStart(e)).toBe(!0),expect(e.confidence).toBe(0)}),it("increases the wildlife tag weight after a wildlife bookmark",()=>{const e=makeEngine().buildProfile([{type:EVENT_TYPES.BOOKMARK,destinationId:"wild-1",timestamp:NOW}]);expect(e.tagWeights.wildlife).toBeGreaterThan(0),expect(AdaptivePreferenceEngine.getTopTags(e,1)).toEqual(["wildlife"])}),it("an unbookmark cancels out a prior bookmark of the same recency",()=>{const e=makeEngine().buildProfile([{type:EVENT_TYPES.BOOKMARK,destinationId:"wild-1",timestamp:NOW},{type:EVENT_TYPES.UNBOOKMARK,destinationId:"wild-1",timestamp:NOW}]);expect(e.tagWeights.wildlife).toBeCloseTo(0,5)}),it("weighs a 5-star rating positively and a 1-star rating negatively",()=>{const e=makeEngine(),t=e.buildProfile([{type:EVENT_TYPES.RATING,destinationId:"wild-1",rating:5,timestamp:NOW}]),i=e.buildProfile([{type:EVENT_TYPES.RATING,destinationId:"wild-1",rating:1,timestamp:NOW}]);expect(t.tagWeights.wildlife).toBeGreaterThan(0),expect(i.tagWeights.wildlife).toBeLessThan(0)}),it("a 3-star rating is neutral",()=>{const e=makeEngine().buildProfile([{type:EVENT_TYPES.RATING,destinationId:"wild-1",rating:3,timestamp:NOW}]);expect(e.tagWeights.wildlife||0).toBeCloseTo(0,5)}),it("decays older events so recent activity dominates",()=>{const e=makeEngine(),t=e.buildProfile([{type:EVENT_TYPES.VIEW,destinationId:"wild-1",timestamp:NOW}]),i=e.buildProfile([{type:EVENT_TYPES.VIEW,destinationId:"wild-1",timestamp:NOW-90*DAY}]);expect(i.tagWeights.wildlife).toBeLessThan(t.tagWeights.wildlife),expect(i.tagWeights.wildlife).toBeGreaterThan(0)}),it("confidence grows with more/stronger signals and eventually exits cold start",()=>{const e=makeEngine(),t=e.buildProfile([{type:EVENT_TYPES.VIEW,destinationId:"wild-1",timestamp:NOW}]),i=e.buildProfile(Array.from({length:6},()=>({type:EVENT_TYPES.BOOKMARK,destinationId:"wild-1",timestamp:NOW})));expect(t.confidence).toBeLessThan(i.confidence),expect(AdaptivePreferenceEngine.isColdStart(t)).toBe(!0),expect(AdaptivePreferenceEngine.isColdStart(i)).toBe(!1)}),it("extracts budget affinity from a planned trip",()=>{const e=makeEngine().buildProfile([{type:EVENT_TYPES.TRIP_PLANNED,budget:2e4,days:2,timestamp:NOW}]);expect(AdaptivePreferenceEngine.getPreferredBudget(e)).toBe("luxury")}),it("a search query matching a known tag contributes to that tag weight",()=>{const e=makeEngine().buildProfile([{type:EVENT_TYPES.SEARCH,query:"best wildlife parks",timestamp:NOW}]);expect(e.tagWeights.wildlife).toBeGreaterThan(0)})});